// Configuration and safety settings
const config = {
  // SAFETY SETTINGS
  dryRun: false, // SET TO FALSE TO ACTUALLY DELETE/MODIFY
  maxEmailsPerBatch: 100, // Process in batches to avoid timeouts
  preserveImportantEmails: true,

  // AGE SETTINGS
  deleteOlderThanDays: 365, // Delete emails older than 1 year
  archiveOlderThanDays: 90,  // Archive emails older than 3 months

  // WHITELIST - Never delete emails from these domains
  protectedDomains: [
    '@company.com',
    '@client.com', 
    '@bank.com',
    '@government.gov',
    // Add your important domains
  ],

  // CATEGORIES TO CLEAN
  categoriesToDelete: [
    'CATEGORY_PROMOTIONS',
    'CATEGORY_SOCIAL',
    'CATEGORY_FORUMS'
  ],

  // LABELS TO REMOVE (old custom labels)
  labelsToRemove: [
    // Add label IDs of old labels you want to remove
    // Example: 'Label_1234567890'
  ],

  // NEW LABEL STRUCTURE
  newLabels: {
    'Work': { color: '#ff0000' },
    'Personal': { color: '#0000ff' },
    'Finance': { color: '#00ff00' },
    'Archive_2024': { color: '#ffff00' },
    'Archive_2023': { color: '#ff8800' },
    'To_Review': { color: '#ff00ff' }
  }
};

console.log('🚀 STARTING COMPLETE MAILBOX CLEANUP');
console.log(`📊 Dry Run Mode: ${config.dryRun ? 'YES (Safe)' : 'NO (Will make changes!)'}`);
console.log(`📅 Will delete emails older than: ${config.deleteOlderThanDays} days`);
console.log(`📦 Will archive emails older than: ${config.archiveOlderThanDays} days`);
console.log(`🛡️ Protected domains: ${config.protectedDomains.length}`);

if (!config.dryRun) {
  console.log('⚠️ WARNING: DRY RUN IS OFF - CHANGES WILL BE PERMANENT!');
}

return { config };

// Apply new categorization
const email = $input.item.json;
const config = $('Setup Configuration').item.json.config;

// Skip if dry run
if (config.dryRun) {
  console.log(`DRY RUN: Would recategorize ${email.subject} as ${email.newCategory}`);
  return email;
}

// Determine new label based on category
let newLabelName = '';
switch (email.newCategory) {
  case 'work':
    newLabelName = 'Work';
    break;
  case 'personal':
    newLabelName = 'Personal';
    break;
  case 'finance':
    newLabelName = 'Finance';
    break;
  case 'archive_2024':
    newLabelName = 'Archive_2024';
    break;
  case 'archive_2023':
    newLabelName = 'Archive_2023';
    break;
  default:
    newLabelName = 'To_Review';
}

email.targetLabel = newLabelName;
return email;

// Create comprehensive cleanup summary
const deletedEmails = $input.all('DELETE Emails') || [];
const archivedEmails = $input.all('ARCHIVE Emails') || [];
const recategorizedEmails = $input.all('Prepare Recategorization') || [];
const config = $('Setup Configuration').item.json.config;

const summary = {
  timestamp: new Date().toISOString(),
  dryRun: config.dryRun,
  totals: {
    deleted: deletedEmails.length,
    archived: archivedEmails.length,
    recategorized: recategorizedEmails.length,
    totalProcessed: deletedEmails.length + archivedEmails.length + recategorizedEmails.length
  },
  categories: {},
  spaceFreed: 0,
  oldestEmailDeleted: null,
  newestEmailDeleted: null
};

// Calculate space freed and date ranges
deletedEmails.forEach(item => {
  const email = item.json;
  summary.spaceFreed += email.sizeEstimate || 0;

  const emailDate = new Date(email.date);
  if (!summary.oldestEmailDeleted || emailDate < new Date(summary.oldestEmailDeleted)) {
    summary.oldestEmailDeleted = email.date;
  }
  if (!summary.newestEmailDeleted || emailDate > new Date(summary.newestEmailDeleted)) {
    summary.newestEmailDeleted = email.date;
  }
});

// Count categories
recategorizedEmails.forEach(item => {
  const category = item.json.newCategory;
  summary.categories[category] = (summary.categories[category] || 0) + 1;
});

// Convert bytes to readable format
function formatBytes(bytes) {
  if (bytes === 0) return '0 Bytes';
  const k = 1024;
  const sizes = ['Bytes', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
}

console.log('\n🎉 MAILBOX CLEANUP COMPLETE!');
console.log('===============================');
console.log(`📊 Mode: ${config.dryRun ? 'DRY RUN (No changes made)' : 'LIVE RUN (Changes applied)'}`);
console.log(`📧 Total emails processed: ${summary.totals.totalProcessed}`);
console.log(`🗑️ Emails deleted: ${summary.totals.deleted}`);
console.log(`📦 Emails archived: ${summary.totals.archived}`);
console.log(`🏷️ Emails recategorized: ${summary.totals.recategorized}`);
console.log(`💾 Space freed: ${formatBytes(summary.spaceFreed)}`);

if (summary.totals.deleted > 0) {
  console.log(`📅 Deleted emails date range: ${summary.oldestEmailDeleted} to ${summary.newestEmailDeleted}`);
}

if (Object.keys(summary.categories).length > 0) {
  console.log('\n📂 New categorization:');
  Object.entries(summary.categories).forEach(([category, count]) => {
    console.log(`   ${category}: ${count} emails`);
  });
}

if (config.dryRun) {
  console.log('\n⚠️ This was a DRY RUN. To apply changes:');
  console.log('   1. Set dryRun: false in the Setup Configuration node');
  console.log('   2. Run the workflow again');
}

return summary;

// Analyze and categorize each email
const email = $input.item.json;
const config = $('Setup Configuration').item.json.config;

// Extract email metadata
const headers = {};
if (email.payload?.headers) {
 email.payload.headers.forEach(header => {
   headers[header.name.toLowerCase()] = header.value;
 });
}

// Safe date parsing with fallback
let emailDate = new Date();
let daysSinceReceived = 0;

if (email.internalDate) {
 const timestamp = parseInt(email.internalDate);
 if (!isNaN(timestamp) && timestamp > 0) {
   emailDate = new Date(timestamp);
   if (isNaN(emailDate.getTime())) {
     // If still invalid, use current date
     emailDate = new Date();
   }
 }
}

const now = new Date();
if (emailDate.getTime() <= now.getTime()) {
 daysSinceReceived = Math.floor((now - emailDate) / (1000 * 60 * 60 * 24));
}

const senderEmail = headers.from || '';
const subject = headers.subject || 'No Subject';
const isImportant = email.labelIds?.includes('IMPORTANT');
const currentLabels = email.labelIds || [];

// Safety checks
const isProtected = config.protectedDomains.some(domain => senderEmail.includes(domain));
const shouldPreserve = isProtected || (config.preserveImportantEmails && isImportant);

// Determine action based on age and content
let action = 'keep';
let newCategory = 'personal';
let reasoning = '';

if (shouldPreserve) {
 action = 'keep';
 reasoning = 'Protected sender or important email';
} else if (daysSinceReceived > config.deleteOlderThanDays) {
 // Very old emails
 if (currentLabels.some(label => config.categoriesToDelete.includes(label))) {
   action = 'delete';
   reasoning = `Promotional/social email older than ${config.deleteOlderThanDays} days`;
 } else {
   action = 'archive';
   newCategory = `archive_${emailDate.getFullYear()}`;
   reasoning = `Old email archived by year`;
 }
} else if (daysSinceReceived > config.archiveOlderThanDays) {
 // Medium age emails
 if (currentLabels.some(label => config.categoriesToDelete.includes(label))) {
   action = 'delete';
   reasoning = 'Promotional email older than archive threshold';
 } else {
   action = 'archive';
   newCategory = `archive_${emailDate.getFullYear()}`;
   reasoning = 'Archive older emails by year';
 }
} else {
 // Recent emails - categorize properly
 if (currentLabels.includes('CATEGORY_PROMOTIONS')) {
   action = 'delete';
   reasoning = 'Recent promotional email';
 } else if (senderEmail.includes('@work.com') || senderEmail.includes('@company.')) {
   newCategory = 'work';
   reasoning = 'Work-related email';
 } else if (senderEmail.includes('@bank.') || subject.toLowerCase().includes('invoice') || subject.toLowerCase().includes('payment')) {
   newCategory = 'finance';
   reasoning = 'Financial email';
 } else {
   newCategory = 'personal';
   reasoning = 'Personal email';
 }
}

const analysis = {
 id: email.id,
 threadId: email.threadId,
 subject: subject,
 from: senderEmail,
 date: emailDate.toISOString(),
 daysSinceReceived: daysSinceReceived,
 currentLabels: currentLabels,
 action: action,
 newCategory: newCategory,
 reasoning: reasoning,
 isProtected: isProtected,
 sizeEstimate: email.sizeEstimate || 0
};

return analysis;
